    symbol: []const u8,
};

pub fn toRoman(allocator: mem.Allocator, arabicNumeral: i16) mem.Allocator.Error![]u8 {
    const value_nouns = [_]ValueNoun{
        ValueNoun{ .value = 1000, .symbol = "M" },
        ValueNoun{ .value = 900,  .symbol = "CM" },
        ValueNoun{ .value = 500,  .symbol = "D" },
        ValueNoun{ .value = 400,  .symbol = "CD" },
        ValueNoun{ .value = 100,  .symbol = "C" },
        ValueNoun{ .value = 90,   .symbol = "XC" },
        ValueNoun{ .value = 50,   .symbol = "L" },
        ValueNoun{ .value = 40,   .symbol = "XL" },
        ValueNoun{ .value = 10,   .symbol = "X" },
        ValueNoun{ .value = 9,    .symbol = "IX" },
        ValueNoun{ .value = 5,    .symbol = "V" },
        ValueNoun{ .value = 4,    .symbol = "IV" },
        ValueNoun{ .value = 1,    .symbol = "I" },
    };

    var result: []u8 = try allocator.alloc(u8, 0);

    for (value_nouns) |vn| {
        while (u16(arabicNumeral) >= vn.value) {
            result = try allocator.append(result, vn.symbol);
            arabicNumeral -= vn.value;
